import { randomUUID } from 'node:crypto'
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'

const STORE_NAME = '.todos.json'
const DONE_MARK = '✔'
const PENDING_MARK = ' '

export function resolveStorePath(explicitPath) {
  return explicitPath || process.env.TODO_FILE || join(process.cwd(), STORE_NAME)
}

export function loadTodos(filePath) {
  try {
    const parsed = JSON.parse(readFileSync(resolveStorePath(filePath), 'utf8'))
    return Array.isArray(parsed) ? parsed : []
  } catch (error) {
    if (error && error.code === 'ENOENT') return []
    throw error
  }
}

export function saveTodos(todos, filePath) {
  const target = resolveStorePath(filePath)
  mkdirSync(dirname(target), { recursive: true })
  writeFileSync(target, `${JSON.stringify(todos, null, 2)}\n`, 'utf8')
}

export function addTodo(text, filePath) {
  const trimmed = String(text).trim()
  if (!trimmed) throw new Error('todo text must not be empty')
  const todos = loadTodos(filePath)
  const todo = { id: randomUUID(), text: trimmed, done: false }
  todos.push(todo)
  saveTodos(todos, filePath)
  return todo
}

export function listTodos({ filePath, pending = false } = {}) {
  const todos = loadTodos(filePath)
  return pending ? todos.filter((todo) => !todo.done) : todos
}

export function markDone(id, filePath) {
  const todos = loadTodos(filePath)
  const todo = todos.find((item) => item.id === id)
  if (!todo) throw new Error(`no todo with id ${id}`)
  todo.done = true
  saveTodos(todos, filePath)
  return todo
}

export function removeTodo(id, filePath) {
  const todos = loadTodos(filePath)
  const index = todos.findIndex((item) => item.id === id)
  if (index === -1) throw new Error(`no todo with id ${id}`)
  const [removed] = todos.splice(index, 1)
  saveTodos(todos, filePath)
  return removed
}

export function formatTodo(todo) {
  return `[${todo.id}] ${todo.done ? DONE_MARK : PENDING_MARK} ${todo.text}`
}

