import { test } from 'node:test'
import assert from 'node:assert/strict'
import { mkdirSync, rmSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import {
  addTodo,
  formatTodo,
  listTodos,
  loadTodos,
  markDone,
  removeTodo,
  resolveStorePath
} from '../src/todos.js'

const STORE_DIR = join(dirname(fileURLToPath(import.meta.url)), '.tmp', 'store')
const STORE = join(STORE_DIR, 'todos.json')

function freshStore() {
  mkdirSync(STORE_DIR, { recursive: true })
  rmSync(STORE, { force: true })
  return STORE
}

test.after(() => rmSync(STORE_DIR, { force: true, recursive: true }))

test('resolveStorePath prefers the explicit path, then TODO_FILE, then .todos.json in the cwd', () => {
  const previous = process.env.TODO_FILE
  try {
    delete process.env.TODO_FILE
    assert.equal(resolveStorePath(), join(process.cwd(), '.todos.json'))
    assert.equal(resolveStorePath('explicit.json'), 'explicit.json')
    process.env.TODO_FILE = 'from-env.json'
    assert.equal(resolveStorePath(), 'from-env.json')
    assert.equal(resolveStorePath('explicit.json'), 'explicit.json')
  } finally {
    if (previous === undefined) delete process.env.TODO_FILE
    else process.env.TODO_FILE = previous
  }
})

test('loadTodos returns an empty list when the store does not exist', () => {
  assert.deepEqual(loadTodos(freshStore()), [])
})

test('addTodo appends a todo with a unique id and done false', () => {
  const filePath = freshStore()
  const first = addTodo('write the plan', filePath)
  const second = addTodo('ship it', filePath)
  assert.notEqual(first.id, second.id)
  assert.equal(first.text, 'write the plan')
  assert.equal(first.done, false)
  assert.deepEqual(loadTodos(filePath).map((todo) => todo.text), ['write the plan', 'ship it'])
})

test('addTodo trims the text and rejects an empty one', () => {
  const filePath = freshStore()
  assert.equal(addTodo('  padded  ', filePath).text, 'padded')
  assert.throws(() => addTodo('   ', filePath), /must not be empty/)
})

test('listTodos returns every todo, and pending true hides the done ones', () => {
  const filePath = freshStore()
  const first = addTodo('first', filePath)
  addTodo('second', filePath)
  markDone(first.id, filePath)
  assert.equal(listTodos({ filePath }).length, 2)
  assert.deepEqual(listTodos({ filePath, pending: true }).map((todo) => todo.text), ['second'])
})

test('markDone flags the todo and throws for an unknown id', () => {
  const filePath = freshStore()
  const todo = addTodo('buy milk', filePath)
  assert.equal(markDone(todo.id, filePath).done, true)
  assert.equal(loadTodos(filePath)[0].done, true)
  assert.throws(() => markDone('nope', filePath), /no todo with id nope/)
})

test('removeTodo deletes only the matching todo and throws for an unknown id', () => {
  const filePath = freshStore()
  const first = addTodo('first', filePath)
  addTodo('second', filePath)
  assert.equal(removeTodo(first.id, filePath).text, 'first')
  assert.deepEqual(loadTodos(filePath).map((todo) => todo.text), ['second'])
  assert.throws(() => removeTodo(first.id, filePath), /no todo with id/)
})

test('formatTodo marks done items with a check mark and keeps the texts aligned', () => {
  assert.equal(formatTodo({ id: 'abc-123', text: 'buy milk', done: false }), '[abc-123]   buy milk')
  assert.equal(formatTodo({ id: 'abc-123', text: 'buy milk', done: true }), '[abc-123] ✔ buy milk')
})

