#!/usr/bin/env node
import {
  addTodo,
  formatTodo,
  listTodos,
  markDone,
  removeTodo
} from '../src/todos.js'

const USAGE = `Usage: todo <command> [options]

  Commands:
    add <text>        Add a todo with the given text
    list [--pending]  List todos; --pending hides the done ones
    done <id>         Mark the todo with <id> as done
    remove <id>       Remove the todo with <id>

  Todos are stored in .todos.json in the directory you run this from.
  Set TODO_FILE to store them somewhere else.`

function main(argv) {
  const [command, ...rest] = argv

  switch (command) {
    case 'add': {
      if (rest.length === 0) throw new Error('add requires a todo text')
      const todo = addTodo(rest.join(' '))
      console.log(`added ${todo.id} ${todo.text}`)
      return 0
    }
    case 'list': {
      const todos = listTodos({ pending: rest.includes('--pending') })
      if (todos.length === 0) {
        console.log('no todos')
        return 0
      }
      for (const todo of todos) console.log(formatTodo(todo))
      return 0
    }
    case 'done': {
      const [id] = rest
      if (!id) throw new Error('done requires a todo id')
      const todo = markDone(id)
      console.log(`done ${todo.id} ${todo.text}`)
      return 0
    }
    case 'remove': {
      const [id] = rest
      if (!id) throw new Error('remove requires a todo id')
      const todo = removeTodo(id)
      console.log(`removed ${todo.id} ${todo.text}`)
      return 0
    }
    case 'help':
    case '--help':
    case '-h':
      console.log(USAGE)
      return 0
    default:
      throw new Error(`unknown command: ${command ?? '(none)'}\n\n${USAGE}`)
  }
}

try {
  process.exitCode = main(process.argv.slice(2))
} catch (error) {
  console.error(`todo: ${error.message}`)
  process.exitCode = 1
}

