import { test } from 'node:test'
import assert from 'node:assert/strict'
import { execFileSync } from 'node:child_process'
import { existsSync, mkdirSync, readFileSync, rmSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..')
const CLI = join(ROOT, 'bin', 'todo.js')
const STORE_DIR = join(ROOT, 'test', '.tmp', 'cli')
const STORE_FILE = join(STORE_DIR, '.todos.json')

function freshStoreDir() {
  mkdirSync(STORE_DIR, { recursive: true })
  rmSync(STORE_FILE, { force: true })
  return STORE_DIR
}

function run(args, { cwd = freshStoreDir(), env = {} } = {}) {
  return execFileSync(process.execPath, [CLI, ...args], {
    cwd,
    encoding: 'utf8',
    env: { ...process.env, ...env },
    stdio: ['ignore', 'pipe', 'pipe']
  })
}

function runFailure(args, { cwd = freshStoreDir(), env = {} } = {}) {
  try {
    run(args, { cwd, env })
  } catch (error) {
    return { status: error.status, stderr: error.stderr }
  }
  throw new Error(`expected todo ${args.join(' ')} to fail`)
}

function addedId(output) {
  const parts = output.trim().split(' ')
  assert.equal(parts[0], 'added')
  assert.equal(parts.length, 3)
  return parts[1]
}

function storedTodos() {
  return JSON.parse(readFileSync(STORE_FILE, 'utf8'))
}

test.after(() => rmSync(STORE_DIR, { force: true, recursive: true }))

test('add writes the store file and prints the new id', () => {
  const line = run(['add', 'buy milk']).trim()
  assert.match(line, /^added \S+ buy milk$/)
  assert.deepEqual(storedTodos(), [{ id: addedId(line), text: 'buy milk', done: false }])
})

test('list marks the done todos with a check mark', () => {
  run(['add', 'first'])
  const second = addedId(run(['add', 'second']))
  run(['done', second])
  const output = run(['list'])
  assert.equal(output.split('\n').filter(Boolean).length, 2)
  assert.match(output, new RegExp(`^\\[${second}\\] ✔ second$`, 'm'))
  assert.match(output, /^\[[^\]]+\] {3}first$/m)
})

test('list --pending hides the done todos', () => {
  run(['add', 'keep me'])
  const hidden = addedId(run(['add', 'hide me']))
  run(['done', hidden])
  const output = run(['list', '--pending'])
  assert.ok(output.includes('keep me'))
  assert.ok(!output.includes('hide me'))
  assert.equal(output.trim().split('\n').length, 1)
})

test('remove deletes the todo from the store', () => {
  const id = addedId(run(['add', 'temporary']))
  assert.equal(run(['remove', id]).trim(), `removed ${id} temporary`)
  assert.deepEqual(storedTodos(), [])
})

test('an empty store lists as "no todos"', () => {
  assert.equal(run(['list']).trim(), 'no todos')
})

test('TODO_FILE redirects the store to another path inside the project', () => {
  const cwd = freshStoreDir()
  const target = join(cwd, 'custom-todos.json')
  run(['add', 'elsewhere'], { cwd, env: { TODO_FILE: target } })
  assert.ok(existsSync(target))
  assert.ok(!existsSync(STORE_FILE))
  assert.ok(readFileSync(target, 'utf8').includes('elsewhere'))
})

test('an unknown command prints the usage on stderr and exits 1', () => {
  const failure = runFailure(['bogus'])
  assert.equal(failure.status, 1)
  assert.match(failure.stderr, /todo: unknown command: bogus/)
  assert.match(failure.stderr, /Usage: todo <command> \[options\]/)
})

test('done with an unknown id exits 1 and prints the error', () => {
  const failure = runFailure(['done', 'missing'])
  assert.equal(failure.status, 1)
  assert.match(failure.stderr, /todo: no todo with id missing/)
})

test('help prints the usage and exits 0', () => {
  assert.match(run(['help']), /Usage: todo <command> \[options\]/)
})

